cat > src/merge.js <<'EOF'
function changes(base, side) {
  const n = base.length, m = side.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--)
    for (let j = m - 1; j >= 0; j--)
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
  const res = []
  let i = 0, j = 0, cur = null
  const flush = () => { if (cur) { res.push(cur); cur = null } }
  const open = () => { if (!cur) cur = { bs: i, be: i, ss: j, se: j } }
  while (i < n || j < m) {
    if (i < n && j < m && base[i] === side[j]) { flush(); i++; j++; continue }
    open()
    if (j >= m || (i < n && L[i + 1][j] >= L[i][j + 1])) i++
    else j++
    cur.be = i; cur.se = j
  }
  flush()
  return res
}

export function merge(mine, base, theirs) {
  const all = [
    ...changes(base, mine).map(c => ({ ...c, side: 0 })),
    ...changes(base, theirs).map(c => ({ ...c, side: 1 })),
  ]
  all.sort((a, b) => a.bs - b.bs || a.side - b.side)
  const sides = [mine, theirs]
  const eq = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])
  const regions = []
  let conflict = false, pos = 0, k = 0
  while (k < all.length) {
    const rs = all[k].bs
    let re = all[k].be
    const group = [all[k++]]
    while (k < all.length && all[k].bs <= re) {
      re = Math.max(re, all[k].be)
      group.push(all[k++])
    }
    if (rs > pos) regions.push({ kind: 'stable', lines: base.slice(pos, rs) })
    pos = re
    const baseL = base.slice(rs, re)
    const rep = [0, 1].map(s => {
      const cs = group.filter(c => c.side === s)
      if (!cs.length) return baseL
      const f = cs.reduce((a, c) => (c.bs < a.bs ? c : a))
      const minBs = f.bs, minSs = Math.min(...cs.map(c => c.ss))
      const maxBe = Math.max(...cs.map(c => c.be)), maxSe = Math.max(...cs.map(c => c.se))
      return sides[s].slice(minSs - (minBs - rs), maxSe + (re - maxBe))
    })
    const [m, t] = rep
    if (eq(m, t)) regions.push({ kind: 'both', lines: m })
    else if (eq(m, baseL)) regions.push({ kind: 'theirs', lines: t })
    else if (eq(t, baseL)) regions.push({ kind: 'mine', lines: m })
    else { conflict = true; regions.push({ kind: 'conflict', mine: m, base: baseL, theirs: t }) }
  }
  if (pos < base.length) regions.push({ kind: 'stable', lines: base.slice(pos) })
  return { regions, conflict }
}
