#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */
import { readFileSync } from 'node:fs'

class Fail extends Error {}
const NAME = /^[A-Za-z0-9_./:-]+$/
const UINT = /^(0|[1-9][0-9]*)$/

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

function int(field, text, least) {
  if (!UINT.test(text) || BigInt(text) < BigInt(least)) {
    throw new Fail(`${field} must be an integer of at least ${least}`)
  }
  return BigInt(text)
}

function makeState(p, tick) {
  if (p.kind === 'bucket') return { scaled: p.capacity * p.per, last: tick }
  return { ticks: [] }
}
function advance(p, s, tick) {
  if (p.kind === 'bucket') {
    const max = p.capacity * p.per
    s.scaled += p.refill * (tick - s.last)
    if (s.scaled > max) s.scaled = max
    s.last = tick
  } else {
    const cut = tick - p.span
    s.ticks = s.ticks.filter((t) => t > cut)
  }
}
function allows(p, s) {
  return p.kind === 'bucket' ? s.scaled >= p.per : BigInt(s.ticks.length) < p.limit
}
function record(p, s, tick) {
  if (p.kind === 'bucket') s.scaled -= p.per
  else s.ticks.push(tick)
}

function run(text) {
  const policies = new Map()
  const routes = new Map()
  const states = new Map()
  const stats = new Map()
  const out = []
  let started = false
  let prev = null
  let prevText = ''
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  lines.forEach((raw, i) => {
    try {
      const line = raw.trim()
      if (line === '' || line.startsWith('#')) return
      const f = line.split(/\s+/)
      const d = f[0]
      const decl = () => {
        if (started) throw new Fail('declarations must come before the first event')
      }
      if (d === 'bucket') {
        if (f.length !== 5) throw new Fail('expected bucket <name> <capacity> <refill> <per>')
        decl()
        if (!NAME.test(f[1])) throw new Fail(`invalid policy name ${f[1]}`)
        const capacity = int('capacity', f[2], 1)
        const refill = int('refill', f[3], 0)
        const per = int('per', f[4], 1)
        if (policies.has(f[1])) throw new Fail(`policy ${f[1]} is declared twice`)
        policies.set(f[1], { kind: 'bucket', name: f[1], capacity, refill, per })
      } else if (d === 'window') {
        if (f.length !== 4) throw new Fail('expected window <name> <limit> <span>')
        decl()
        if (!NAME.test(f[1])) throw new Fail(`invalid policy name ${f[1]}`)
        const limit = int('limit', f[2], 0)
        const span = int('span', f[3], 1)
        if (policies.has(f[1])) throw new Fail(`policy ${f[1]} is declared twice`)
        policies.set(f[1], { kind: 'window', name: f[1], limit, span })
      } else if (d === 'route') {
        if (f.length < 3) throw new Fail('expected route <prefix> <policy>...')
        decl()
        if (!NAME.test(f[1])) throw new Fail(`invalid route prefix ${f[1]}`)
        if (routes.has(f[1])) throw new Fail(`prefix ${f[1]} is routed twice`)
        const list = f.slice(2).map((n) => {
          if (!policies.has(n)) throw new Fail(`unknown policy ${n}`)
          return policies.get(n)
        })
        routes.set(f[1], list)
      } else if (d === 'event') {
        if (f.length !== 3) throw new Fail('expected event <tick> <key>')
        const tick = int('tick', f[1], 0)
        const key = f[2]
        if (!NAME.test(key)) throw new Fail(`invalid key ${key}`)
        if (prev !== null && tick < prev) throw new Fail(`tick ${f[1]} is before tick ${prevText}`)
        started = true
        prev = tick
        prevText = f[1]
        let best = null
        for (const pre of routes.keys()) {
          if (key.startsWith(pre) && (best === null || pre.length > best.length)) best = pre
        }
        let denied = null
        if (best !== null) {
          const list = routes.get(best)
          const ss = list.map((p) => {
            const id = p.name + '\0' + key
            let s = states.get(id)
            if (!s) states.set(id, (s = makeState(p, tick)))
            advance(p, s, tick)
            return s
          })
          for (let j = 0; j < list.length; j++) {
            if (!allows(list[j], ss[j])) { denied = list[j].name; break }
          }
          if (denied === null) list.forEach((p, j) => record(p, ss[j], tick))
        }
        const st = stats.get(key) || { a: 0, d: 0 }
        stats.set(key, st)
        if (denied === null) st.a++
        else st.d++
        out.push(`${f[1]} ${key} ${denied === null ? 'allow' : 'deny ' + denied}`)
      } else {
        throw new Fail(`unknown directive ${d}`)
      }
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${i + 1}: ${e.message}`)
      throw e
    }
  })
  if (mode === 'replay') return out.length ? out.join('\n') + '\n' : ''
  const keys = [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
  let ta = 0
  let td = 0
  const res = keys.map((k) => {
    const s = stats.get(k)
    ta += s.a
    td += s.d
    return `${k} allowed=${s.a} denied=${s.d}`
  })
  res.push(`total allowed=${ta} denied=${td}`)
  return res.join('\n') + '\n'
}

try {
  process.stdout.write(run(readFileSync(0, 'utf8')))
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
EOF
