const mode = process.argv.length === 3 ? process.argv[2] : null
function fail(msg) { process.stderr.write(msg + '\n'); process.exit(2) }
if (mode !== 'rounds' && mode !== 'tally') fail('error: usage: cli.js rounds|tally')

import('node:fs').then(({ readFileSync }) => main(readFileSync(0, 'utf8')))

function main(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  let cands = null
  const set = new Set()
  const ballots = []
  for (let i = 0; i < lines.length; i++) {
    const n = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const t = line.split(/\s+/)
    if (t[0] === 'candidates') {
      if (cands !== null || ballots.length > 0) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
      if (t.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
      cands = []
      for (const name of t.slice(1)) {
        if (!/^[A-Za-z0-9_-]+$/.test(name)) fail(`error: line ${n}: invalid candidate name ${name}`)
        if (set.has(name)) fail(`error: line ${n}: candidate ${name} is declared twice`)
        set.add(name); cands.push(name)
      }
    } else if (t[0] === 'ballot') {
      if (cands === null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
      if (t.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
      if (!/^[1-9][0-9]*$/.test(t[1])) fail(`error: line ${n}: count must be a positive integer`)
      const seen = new Set()
      for (const name of t.slice(2)) {
        if (!set.has(name)) fail(`error: line ${n}: unknown candidate ${name}`)
        if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count: Number(t[1]), prefs: t.slice(2) })
    } else {
      fail(`error: line ${n}: unknown directive ${t[0]}`)
    }
  }
  if (cands === null) fail('error: no candidates')

  const cont = new Set(cands)
  const hist = [] // per round: Map name->votes
  let out = ''
  let result = 'no winner'
  let rounds = 0
  for (;;) {
    rounds++
    const counts = new Map([...cont].map(c => [c, 0]))
    let active = 0, exhausted = 0
    for (const b of ballots) {
      const c = b.prefs.find(p => cont.has(p))
      if (c === undefined) exhausted += b.count
      else { counts.set(c, counts.get(c) + b.count); active += b.count }
    }
    hist.push(counts)
    const list = [...counts.entries()].sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
    out += `round ${rounds}: ${list.map(([k, v]) => `${k}=${v}`).join(' ')} exhausted=${exhausted}\n`
    if (active === 0) break
    const w = list.find(([, v]) => v * 2 > active)
    if (w) { result = `winner ${w[0]}`; break }
    let pool = [...cont]
    const min = Math.min(...pool.map(c => counts.get(c)))
    pool = pool.filter(c => counts.get(c) === min)
    while (pool.length > 1) {
      let reduced = false
      for (const h of hist) {
        const vs = pool.map(c => h.get(c))
        const m = Math.min(...vs)
        if (vs.some(v => v !== m)) { pool = pool.filter(c => h.get(c) === m); reduced = true; break }
      }
      if (!reduced) break
    }
    const el = pool.reduce((a, b) => (a > b ? a : b))
    cont.delete(el)
    out += `eliminated ${el}\n`
  }
  process.stdout.write(mode === 'rounds' ? `${out}${result}\n` : `rounds ${rounds}\n${result}\n`)
}
EOF
