const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = '+-*/%=<>!(){}[],;.'
const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdChar = (c) => isLetter(c) || isDigit(c) || c === '_'
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== undefined && c >= '0' && c <= '7'

export class ScanError extends Error {
  constructor(line, col, reason) {
    super(`${line}:${col}: ${reason}`)
  }
}

export function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  const tokens = []
  let i = 0
  let line = 1
  let col = 1

  const adv = () => {
    const c = cs[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = (Math.floor((col - 1) / 4) + 1) * 4 + 1
    else col++
    return c
  }
  const advN = (k) => { while (k-- > 0) adv() }

  // digit run with single underscores between digits; returns end index
  const run = (j, isD) => {
    while (j < n) {
      if (isD(cs[j])) j++
      else if (cs[j] === '_' && j > 0 && isD(cs[j - 1]) && isD(cs[j + 1])) j++
      else break
    }
    return j
  }

  while (i < n) {
    const c = cs[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') adv()
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      const sl = line, sc = col
      advN(2)
      let depth = 1
      while (depth > 0) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated block comment')
        if (cs[i] === '/' && cs[i + 1] === '*') { advN(2); depth++ }
        else if (cs[i] === '*' && cs[i + 1] === '/') { advN(2); depth-- }
        else adv()
      }
      continue
    }
    const sl = line, sc = col
    if (c === 'r' && cs[i + 1] === '"') {
      let j = i + 2
      while (j < n && cs[j] !== '"') j++
      if (j >= n) throw new ScanError(sl, sc, 'unterminated string')
      const value = cs.slice(i + 2, j).join('')
      advN(j + 1 - i)
      tokens.push({ line: sl, col: sc, kind: 'rawstring', body: JSON.stringify(value) })
      continue
    }
    if (isLetter(c) || c === '_') {
      let j = i
      while (j < n && isIdChar(cs[j])) j++
      const word = cs.slice(i, j).join('')
      advN(j - i)
      tokens.push({ line: sl, col: sc, kind: KEYWORDS.has(word) ? 'keyword' : 'ident', body: word })
      continue
    }
    if (isDigit(c)) {
      let j = i
      let bad = false
      const p = cs[i + 1]
      const pre = c === '0' && p !== undefined ? p.toLowerCase() : ''
      const radix = { x: isHex, b: isBin, o: isOct }[pre]
      if (radix) {
        j = i + 2
        if (!radix(cs[j])) bad = true
        else j = run(j, radix)
      } else {
        j = run(i, isDigit)
        if (cs[j] === '.' && isDigit(cs[j + 1])) j = run(j + 1, isDigit)
        if (cs[j] === 'e' || cs[j] === 'E') {
          if (isDigit(cs[j + 1])) j = run(j + 1, isDigit)
          else if ((cs[j + 1] === '+' || cs[j + 1] === '-') && isDigit(cs[j + 2])) j = run(j + 2, isDigit)
        }
      }
      if (bad || isIdChar(cs[j])) {
        while (j < n && isIdChar(cs[j])) j++
        throw new ScanError(sl, sc, `invalid number ${cs.slice(i, j).join('')}`)
      }
      const body = cs.slice(i, j).join('')
      advN(j - i)
      tokens.push({ line: sl, col: sc, kind: 'number', body })
      continue
    }
    if (c === '"') {
      adv()
      let value = ''
      for (;;) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const ch = cs[i]
        if (ch === '"') { adv(); break }
        if (ch === '\n') throw new ScanError(line, col, 'newline in string')
        if (ch !== '\\') { value += ch; adv(); continue }
        const bl = line, bc = col
        adv()
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const e = cs[i]
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', '0': '\0' }
        const invalid = () => new ScanError(bl, bc, `invalid escape \\${e}`)
        if (e in simple) { value += simple[e]; adv() }
        else if (e === 'x') {
          if (!isHex(cs[i + 1]) || !isHex(cs[i + 2])) throw invalid()
          value += String.fromCharCode(parseInt(cs[i + 1] + cs[i + 2], 16))
          advN(3)
        } else if (e === 'u') {
          if (cs[i + 1] !== '{') throw invalid()
          let j = i + 2
          while (isHex(cs[j])) j++
          if (j === i + 2 || cs[j] !== '}') throw invalid()
          const cp = parseInt(cs.slice(i + 2, j).join(''), 16)
          if (cp > 0x10ffff) throw invalid()
          value += String.fromCodePoint(cp)
          advN(j + 1 - i)
        } else throw invalid()
      }
      tokens.push({ line: sl, col: sc, kind: 'string', body: JSON.stringify(value) })
      continue
    }
    const two = c + (cs[i + 1] ?? '')
    if (PUNCT2.includes(two)) {
      advN(2)
      tokens.push({ line: sl, col: sc, kind: 'punct', body: two })
      continue
    }
    if (PUNCT1.includes(c)) {
      adv()
      tokens.push({ line: sl, col: sc, kind: 'punct', body: c })
      continue
    }
    throw new ScanError(sl, sc, `unexpected character ${c}`)
  }
  return tokens
}
EOF
