const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

class Fail extends Error {}
const NAME = /^[A-Za-z0-9_./:-]+$/
const UINT = /^(0|[1-9][0-9]*)$/

function uint(field, text, least) {
  if (!UINT.test(text) || BigInt(text) < BigInt(least)) {
    throw new Fail(`${field} must be an integer of at least ${least}`)
  }
  return BigInt(text)
}

const policies = new Map()
const routes = new Map()
const states = new Map()
const stats = new Map()
const out = []
let started = false
let lastTick = null

function makeState(p, tick) {
  if (p.type === 'bucket') return { s: p.capacity * p.per, last: tick }
  return { ticks: [] }
}
function advance(p, st, tick) {
  if (p.type === 'bucket') {
    const cap = p.capacity * p.per
    st.s += p.refill * (tick - st.last)
    if (st.s > cap) st.s = cap
    st.last = tick
  } else {
    const cut = tick - p.span
    let i = 0
    while (i < st.ticks.length && st.ticks[i] <= cut) i++
    if (i) st.ticks.splice(0, i)
  }
}
const allows = (p, st) => (p.type === 'bucket' ? st.s >= p.per : BigInt(st.ticks.length) < p.limit)
function record(p, st, tick) {
  if (p.type === 'bucket') st.s -= p.per
  else st.ticks.push(tick)
}

function handle(w) {
  const d = w[0]
  if (d === 'bucket' || d === 'window' || d === 'route') {
    if (started) throw new Fail('declarations must come before the first event')
  }
  if (d === 'bucket') {
    if (w.length !== 5) throw new Fail('expected bucket <name> <capacity> <refill> <per>')
    if (!NAME.test(w[1])) throw new Fail(`invalid policy name ${w[1]}`)
    const capacity = uint('capacity', w[2], 1)
    const refill = uint('refill', w[3], 0)
    const per = uint('per', w[4], 1)
    if (policies.has(w[1])) throw new Fail(`policy ${w[1]} is declared twice`)
    policies.set(w[1], { type: 'bucket', name: w[1], capacity, refill, per })
  } else if (d === 'window') {
    if (w.length !== 4) throw new Fail('expected window <name> <limit> <span>')
    if (!NAME.test(w[1])) throw new Fail(`invalid policy name ${w[1]}`)
    const limit = uint('limit', w[2], 0)
    const span = uint('span', w[3], 1)
    if (policies.has(w[1])) throw new Fail(`policy ${w[1]} is declared twice`)
    policies.set(w[1], { type: 'window', name: w[1], limit, span })
  } else if (d === 'route') {
    if (w.length < 3) throw new Fail('expected route <prefix> <policy>...')
    if (!NAME.test(w[1])) throw new Fail(`invalid route prefix ${w[1]}`)
    if (routes.has(w[1])) throw new Fail(`prefix ${w[1]} is routed twice`)
    for (const n of w.slice(2)) if (!policies.has(n)) throw new Fail(`unknown policy ${n}`)
    routes.set(w[1], w.slice(2).map((n) => policies.get(n)))
  } else if (d === 'event') {
    if (w.length !== 3) throw new Fail('expected event <tick> <key>')
    const key = w[2]
    if (!NAME.test(key)) throw new Fail(`invalid key ${key}`)
    const tick = uint('tick', w[1], 0)
    if (lastTick !== null && tick < lastTick) throw new Fail(`tick ${tick} is before tick ${lastTick}`)
    lastTick = tick
    started = true
    let best = null
    for (const pre of routes.keys()) {
      if (key.startsWith(pre) && (best === null || pre.length > best.length)) best = pre
    }
    let denied = null
    if (best !== null) {
      const list = routes.get(best)
      const sts = list.map((p) => {
        const id = p.name + '\0' + key
        let st = states.get(id)
        if (!st) states.set(id, (st = makeState(p, tick)))
        advance(p, st, tick)
        return st
      })
      for (let i = 0; i < list.length; i++) {
        if (!allows(list[i], sts[i])) { denied = list[i]; break }
      }
      if (!denied) list.forEach((p, i) => record(p, sts[i], tick))
    }
    const s = stats.get(key) || (stats.set(key, { a: 0, d: 0 }), stats.get(key))
    if (denied) s.d++; else s.a++
    if (mode === 'replay') out.push(`${tick} ${key} ${denied ? 'deny ' + denied.name : 'allow'}`)
  } else {
    throw new Fail(`unknown directive ${d}`)
  }
}

const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()
try {
  lines.forEach((raw, i) => {
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    try {
      handle(line.split(/\s+/))
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${i + 1}: ${e.message}`)
      throw e
    }
  })
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}

if (mode === 'summary') {
  let ta = 0
  let td = 0
  for (const k of [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))) {
    const s = stats.get(k)
    ta += s.a
    td += s.d
    out.push(`${k} allowed=${s.a} denied=${s.d}`)
  }
  out.push(`total allowed=${ta} denied=${td}`)
}
process.stdout.write(out.length ? out.join('\n') + '\n' : '')
