export class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const PUNCT1 = new Set('+-*/%=<>!(){}[],;.'.split(''))
const isLetter = (c) => c !== undefined && /^[A-Za-z]$/.test(c)
const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isIdentChar = (c) => isLetter(c) || isDigit(c) || c === '_'
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== undefined && c >= '0' && c <= '7'

export function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  // position of each code point index
  const lines = new Array(n + 1)
  const cols = new Array(n + 1)
  let l = 1, c = 1
  for (let i = 0; i < n; i++) {
    lines[i] = l
    cols[i] = c
    if (cs[i] === '\n') { l++; c = 1 }
    else if (cs[i] === '\t') c = Math.floor((c - 1) / 4) * 4 + 5
    else c++
  }
  lines[n] = l
  cols[n] = c
  const err = (i, reason) => new ScanError(lines[i], cols[i], reason)
  const toks = []
  let i = 0

  // digit run with single underscores between digits; returns new index
  const run = (j, isD) => {
    while (j < n) {
      if (isD(cs[j])) j++
      else if (cs[j] === '_' && j > 0 && isD(cs[j - 1]) && isD(cs[j + 1])) j++
      else break
    }
    return j
  }

  while (i < n) {
    const ch = cs[i]
    if (ch === ' ' || ch === '\t' || ch === '\r' || ch === '\n') { i++; continue }
    if (ch === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') i++
      continue
    }
    if (ch === '/' && cs[i + 1] === '*') {
      const start = i
      let depth = 1
      i += 2
      while (i < n && depth > 0) {
        if (cs[i] === '/' && cs[i + 1] === '*') { depth++; i += 2 }
        else if (cs[i] === '*' && cs[i + 1] === '/') { depth--; i += 2 }
        else i++
      }
      if (depth > 0) throw err(start, 'unterminated block comment')
      continue
    }
    if (ch === 'r' && cs[i + 1] === '"') {
      let j = i + 2
      while (j < n && cs[j] !== '"') j++
      if (j >= n) throw err(i, 'unterminated string')
      const value = cs.slice(i + 2, j).join('')
      toks.push({ line: lines[i], col: cols[i], kind: 'rawstring', body: JSON.stringify(value) })
      i = j + 1
      continue
    }
    if (isLetter(ch) || ch === '_') {
      let j = i + 1
      while (j < n && isIdentChar(cs[j])) j++
      const s = cs.slice(i, j).join('')
      toks.push({ line: lines[i], col: cols[i], kind: KEYWORDS.has(s) ? 'keyword' : 'ident', body: s })
      i = j
      continue
    }
    if (isDigit(ch)) {
      let j = i
