  const lines = readFileSync(0, 'utf8').split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  root = parseDocument(lines)
} catch (e) {
  if (e && e.isConfigError) {
    process.stderr.write(`error: line ${e.line}: ${e.message}\n`)
    process.exit(2)
  }
  throw e
}
