const fail = (msg) => {
  const e = new Error(msg)
  e.isConfigError = true
  throw e
}

const INT = /^[+-]?[0-9]+(_[0-9]+)*$/
const FLOAT = /^[+-]?[0-9]+(_[0-9]+)*(\.[0-9]+(_[0-9]+)*)?([eE][+-]?[0-9]+(_[0-9]+)*)?$/
const isWs = (c) => c === ' ' || c === '\t'
const isBare = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)

const newTable = () => ({ t: 'table', m: new Map(), hdr: false })

function walk(tbl, names, base) {
  let path = base.slice()
  for (const name of names) {
    path.push(name)
    let c = tbl.m.get(name)
    if (!c) {
      c = newTable()
      tbl.m.set(name, c)
    } else if (c.t === 'array' && c.aot) c = c.items[c.items.length - 1]
    else if (c.t !== 'table') fail(`${path.join('.')} is not a table`)
    tbl = c
  }
  return tbl
}

function assign(tbl, names, value, base) {
  const parent = walk(tbl, names.slice(0, -1), base)
  const last = names[names.length - 1]
  if (parent.m.has(last)) fail(`key ${[...base, ...names].join('.')} is defined twice`)
  parent.m.set(last, value)
}

