export function parse(s) {
  const u = { scheme: null, authority: null, path: '', query: null, fragment: null }
  let m = /^([^:/?#]+):/.exec(s)
  if (m) {
    u.scheme = m[1]
    s = s.slice(m[0].length)
  }
  if (s.startsWith('//')) {
    const rest = s.slice(2)
    const end = rest.search(/[/?#]/)
    u.authority = end < 0 ? rest : rest.slice(0, end)
    s = end < 0 ? '' : rest.slice(end)
  }
  const h = s.indexOf('#')
  if (h >= 0) {
    u.fragment = s.slice(h + 1)
    s = s.slice(0, h)
  }
  const q = s.indexOf('?')
  if (q >= 0) {
    u.query = s.slice(q + 1)
    s = s.slice(0, q)
  }
  u.path = s
  return u
}

export function splitAuthority(a) {
  const at = a.lastIndexOf('@')
  const userinfo = at >= 0 ? a.slice(0, at) : null
  const rest = at >= 0 ? a.slice(at + 1) : a
  const rb = rest.lastIndexOf(']')
  const colon = rest.indexOf(':', rb + 1)
  if (colon < 0) return { userinfo, host: rest, port: null }
  return { userinfo, host: rest.slice(0, colon), port: rest.slice(colon + 1) }
}

function checkPct(s, name, line) {
  if (s === null) return
  if (/%(?![0-9A-Fa-f]{2})/.test(s)) {
    throw new UriError(`error: line ${line}: the ${name} has a truncated percent-encoding`)
  }
}

export function validate(u, line) {
  let ui = null
  let host = null
  if (u.authority !== null) {
    const a = splitAuthority(u.authority)
    ui = a.userinfo
    host = a.host
  }
  checkPct(u.path, 'path', line)
  checkPct(ui, 'userinfo', line)
  checkPct(host, 'host', line)
  checkPct(u.query, 'query', line)
  checkPct(u.fragment, 'fragment', line)
}

function pct(s) {
  if (s === null) return null
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const up = h.toUpperCase()
    const c = String.fromCharCode(parseInt(up, 16))
    return /[A-Za-z0-9\-._~]/.test(c) ? c : '%' + up
  })
}

const lower = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())
const DEFAULT_PORT = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export function removeDots(path) {
  let inp = path
  let out = ''
  while (inp.length) {
    if (inp.startsWith('../')) inp = inp.slice(3)
    else if (inp.startsWith('./')) inp = inp.slice(2)
    else if (inp.startsWith('/./')) inp = inp.slice(2)
    else if (inp === '/.') inp = '/'
    else if (inp.startsWith('/../') || inp === '/..') {
      inp = inp === '/..' ? '/' : inp.slice(3)
      out = out.slice(0, Math.max(0, out.lastIndexOf('/')))
    } else if (inp === '.' || inp === '..') inp = ''
    else {
      const i = inp.indexOf('/', 1)
      const seg = i < 0 ? inp : inp.slice(0, i)
      out += seg
      inp = inp.slice(seg.length)
    }
  }
  return out
}

export function serialize(u) {
  let r = ''
  if (u.scheme !== null) r += u.scheme + ':'
  if (u.authority !== null) r += '//' + u.authority
  r += u.path
  if (u.query !== null) r += '?' + u.query
  if (u.fragment !== null) r += '#' + u.fragment
  return r
}

export function normalize(u) {
  const scheme = u.scheme === null ? null : lower(u.scheme)
  let authority = null
  if (u.authority !== null) {
    const a = splitAuthority(pct(u.authority))
