{"file_path":"src/cli.js","content":"import { readFileSync } from 'node:fs'

const ERRS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (code) => ({ k: 'err', v: code })
const num = (v) => ({ k: 'num', v })
const str = (v) => ({ k: 'str', v })
const bool = (v) => ({ k: 'bool', v })

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const mode = process.argv.slice(2)
if (mode.length !== 1 || (mode[0] !== 'values' && mode[0] !== 'deps')) fail('error: usage: cli.js values|deps')

// ---- address helpers
function colIndex(letters) {
  let n = 0
  for (const ch of letters) n = n * 26 + (ch.charCodeAt(0) - 64)
  return n
}
function colName(i) {
  return i <= 26 ? String.fromCharCode(64 + i) : String.fromCharCode(64 + Math.floor((i - 1) / 26)) + String.fromCharCode(65 + ((i - 1) % 26))
}
function parseAddr(w) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(w)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  return { col: colIndex(m[1].toUpperCase()), row }
}
const keyOf = (c, r) => c * 1000 + r
const nameOf = (c, r) => colName(c) + r

// ---- sheet parsing
let input = readFileSync(0, 'utf8')
const lines = input.split('\n')
if (lines[lines.length - 1] === '') lines.pop()
const cells = new Map()
lines.forEach((raw, i) => {
  const s = raw.replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') return
  const m = /^([^ \t]*)[ \t]?/.exec(s)
  let end = 0
  while (end < s.length && s[end] !== ' ' && s[end] !== '\t') end++
  const word = s.slice(0, end)
  let p = end
  while (p < s.length && (s[p] === ' ' || s[p] === '\t')) p++
  void m
  const content = s.slice(p)
  const a = parseAddr(word)
  if (!a) fail(`error: line ${i + 1}: invalid cell address ${word}`)
  const k = keyOf(a.col, a.row)
  if (cells.has(k)) fail(`error: line ${i + 1}: cell ${word.toUpperCase()} is declared twice`)
  cells.set(k, { col: a.col, row: a.row, content })
})

// ---- formula parser
function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) { toks.push({ t: 'num', v: Number(m[0]) }); i += m[0].length; continue }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) { toks.push({ t: 'word', v: m[0] }); i += m[0].length; continue }
    if ((m = /^(<>|<=|>=)/.exec(s.slice(i)))) { toks.push({ t: 'op', v: m[0] }); i += 2; continue }
    if ('^*/+-=<>():,'.includes(c)) { toks.push({ t: 'op', v: c }); i++; continue }
    throw new Error('lex')
  }
  return toks
}

function parseFormula(body) {
  const toks = tokenize(body)
  let p = 0
  const isOp = (v) => p < toks.length && toks[p].t === 'op' && toks[p].v === v
  const bad = () => { throw new Error('parse') }
  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { n: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) { const op = toks[p++].v; l = { n: 'bin', op, l, r: mul() } }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) { const op = toks[p++].v; l = { n: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { n: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) { const op = toks[p++].v; return { n: 'un', op, e: unary() } }
    return primary()
  }
  function primary() {
    if (p >= toks.length) bad()
    const t = toks[p]
    if (t.t === 'num') { p++; return { n: 'num', v: t.v } }
    if (t.t === 'op' && t.v === '(') {
      p++
      const e = cmp()
      if (!isOp(')')) bad()
      p++
      return { n: 'paren', e }
    }
    if (t.t === 'word') {
      p++
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) { p++ } else {
          for (;;) {
            args.push(cmp())
            if (isOp(',')) { p++; continue }
            if (isOp(')')) { p++; break }
            bad()
          }
        }
        return { n: 'call', name: t.v.toUpperCase(), args }
      }
      const up = t.v.toUpperCase()
      if (up === 'TRUE') return { n: 'bool', v: true }
      if (up === 'FALSE') return { n: 'bool', v: false }
      if (isOp(':')) {
        p++
        if (p >= toks.length || toks[p].t !== 'word') bad()
        const w2 = toks[p++].v
        return { n: 'range', a: t.v, b: w2, a1: parseAddr(t.v), b1: parseAddr(w2) }
      }
      return { n: 'ref', w: t.v, a: parseAddr(t.v) }
    }
    bad()
  }
  const e = cmp()
  if (p !== toks.length) bad()
  return e
}

for (const c of cells.values()) {
  const s = c.content
  c.ast = null
  if (s[0] === '=') {
    try { c.ast = parseFormula(s.slice(1)) } catch { c.ast = null; c.bad = true }
  }
}

// ---- deps
function collectRefs(n, set) {
  switch (n.n) {
    case 'ref': if (n.a) set.set(keyOf(n.a.col, n.a.row), n.a); break
    case 'range':
      if (n.a1 && n.b1) {
        const c0 = Math.min(n.a1.col, n.b1.col), c1 = Math.max(n.a1.col, n.b1.col)
        const r0 = Math.min(n.a1.row, n.b1.row), r1 = Math.max(n.a1.row, n.b1.row)
        for (let c = c0; c <= c1; c++) for (let r = r0; r <= r1; r++) set.set(keyOf(c, r), { col: c, row: r })
      }
      break
    case 'bin': collectRefs(n.l, set); collectRefs(n.r, set); break
    case 'un': case 'paren': collectRefs(n.e, set); break
    case 'call': n.args.forEach((a) => collectRefs(a, set)); break
  }
}

const sorted = [...cells.values()].sort((a, b) => a.col - b.col || a.row - b.row)

if (mode[0] === 'deps') {
  let out = ''
  for (const c of sorted) {
    let line = nameOf(c.col, c.row) + ':'
    if (c.ast) {
      const set = new Map()
      collectRefs(c.ast, set)
      const list = [...set.values()].sort((a, b) => a.col - b.col || a.row - b.row)
      for (const a of list) line += ' ' + nameOf(a.col, a.row)
    }
    out += line + '\n'
  }
  process.stdout.write(out)
  process.exit(0)
}

// ---- evaluation
const memo = new Map()
const visiting = new Set()

function literal(s) {
  if (s === '') return num(0)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(s)) return num(Number(s))
  if (ERRS.includes(s)) return err(s)
  return str(s)
}

function cellValue(col, row) {
  const k = keyOf(col, row)
  const c = cells.get(k)
  if (!c) return num(0)
  if (memo.has(k)) return memo.get(k)
  if (visiting.has(k)) return err('#CYCLE!')
  visiting.add(k)
  let v
  if (c.content[0] === '=') v = c.ast ? evalNode(c.ast) : err('#ERR!')
  else v = literal(c.content)
  visiting.delete(k)
  memo.set(k, v)
  return v
}

function toNum(v) {
  if (v.k === 'err') return v
  if (v.k === 'num') return v
  if (v.k === 'bool') return num(v.v ? 1 : 0)
  return err('#VALUE!')
}
const finite = (x) => (Number.isFinite(x) ? num(x) : err('#DIV/0!'))

function cpCompare(a, b) {
  const x = Array.from(a), y = Array.from(b)
  const n = Math.min(x.length, y.length)
