{"file_path":"src/eval.js","content":"import { addrParts, colIndex, colName } from './util.js'

const num = (v) => ({ k: 'n', v })
const err = (v) => ({ k: 'e', v })
const ERRORS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']

function literal(content) {
  if (content === '') return num(0)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return num(Number(content))
  if (ERRORS.includes(content)) return err(content)
  return { k: 't', v: content }
}

function cmpCode(a, b) {
  const x = Array.from(a)
  const y = Array.from(b)
  for (let i = 0; i < Math.min(x.length, y.length); i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
const rank = { n: 0, t: 1, b: 2 }

export function evaluateAll(cells) {
  const memo = new Map()
  const busy = new Set()

  function cellValue(addr) {
    const p = addrParts(addr)
    if (!p) return err('#REF!')
    if (memo.has(addr)) return memo.get(addr)
    const c = cells.get(addr)
    if (!c) return num(0)
    if (busy.has(addr)) return err('#CYCLE!')
    busy.add(addr)
    let v
    if (c.content[0] === '=') v = c.ast.err ? err('#ERR!') : ev(c.ast)
    else v = literal(c.content)
    busy.delete(addr)
    memo.set(addr, v)
    return v
  }

  function toNum(v) {
    if (v.k === 'n') return v
    if (v.k === 'b') return num(v.v ? 1 : 0)
    if (v.k === 'e') return v
    return err('#VALUE!')
  }
  const fin = (x) => (Number.isFinite(x) ? num(x) : err('#DIV/0!'))

  function expand(n) {
    const a = addrParts(n.a)
    const b = addrParts(n.b)
    if (!a || !b) return [err('#REF!')]
    const c1 = Math.min(colIndex(a.col), colIndex(b.col))
    const c2 = Math.max(colIndex(a.col), colIndex(b.col))
    const r1 = Math.min(a.row, b.row)
    const r2 = Math.max(a.row, b.row)
    const out = []
    for (let c = c1; c <= c2; c++) for (let r = r1; r <= r2; r++) out.push(cellValue(colName(c) + r))
    return out
  }

  function call(n) {
    const name = n.name
    const k = n.args.length
    const known = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF']
    if (!known.includes(name)) return err('#NAME?')
    if (name === 'IF') {
      if (k !== 3 || n.args.some((a) => a.t === 'range')) return err('#ERR!')
      const c = ev(n.args[0])
      if (c.k === 'e') return c
      let truth
      if (c.k === 'b') truth = c.v
      else if (c.k === 'n') truth = c.v !== 0
      else return err('#VALUE!')
      return ev(truth ? n.args[1] : n.args[2])
    }
    if (name === 'ABS') {
      if (k !== 1 || n.args[0].t === 'range') return err('#ERR!')
      const v = toNum(ev(n.args[0]))
      return v.k === 'n' ? num(Math.abs(v.v)) : v
    }
    if (k < 1) return err('#ERR!')
    const vals = []
    for (const a of n.args) {
      if (a.t === 'range') vals.push(...expand(a))
      else vals.push(ev(a))
    }
    const e = vals.find((v) => v.k === 'e')
    if (e) return e
    if (name === 'COUNT') return num(vals.filter((v) => v.k === 'n').length)
    const ns = []
    for (const v of vals) {
      const x = toNum(v)
      if (x.k === 'e') return x
      ns.push(x.v)
    }
    if (name === 'SUM') return fin(ns.reduce((s, x) => s + x, 0))
    if (name === 'AVG') return fin(ns.reduce((s, x) => s + x, 0) / ns.length)
    if (name === 'MIN') return num(ns.reduce((s, x) => (x < s ? x : s)))
    return num(ns.reduce((s, x) => (x > s ? x : s)))
  }

  function ev(n) {
    switch (n.t) {
      case 'num':
        return num(n.v)
      case 'bool':
        return { k: 'b', v: n.v }
      case 'ref':
        return cellValue(n.addr)
      case 'range':
        return err('#ERR!')
      case 'call':
        return call(n)
      case 'un': {
        const v = toNum(ev(n.e))
        if (v.k !== 'n') return v
        return n.op === '-' ? num(-v.v) : v
      }
      case 'bin': {
        const l = ev(n.l)
        const r = ev(n.r)
        if (l.k === 'e') return l
        if (r.k === 'e') return r
        if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
          let d
          if (l.k !== r.k) d = rank[l.k] - rank[r.k]
          else if (l.k === 'n') d = l.v < r.v ? -1 : l.v > r.v ? 1 : 0
