        }
        const a = toNum(l)
        if (a.k !== 'n') return a
        const b = toNum(r)
        if (b.k !== 'n') return b
        switch (n.op) {
          case '+':
            return fin(a.v + b.v)
          case '-':
            return fin(a.v - b.v)
          case '*':
            return fin(a.v * b.v)
          case '/':
            return b.v === 0 ? err('#DIV/0!') : fin(a.v / b.v)
          default:
            return fin(Math.pow(a.v, b.v))
        }
      }
    }
    return err('#ERR!')
  }

  const res = new Map()
  for (const addr of cells.keys()) res.set(addr, cellValue(addr))
  return res
}
