          if (l.k !== r.k) d = rank[l.k] - rank[r.k]
          else if (l.k === 'n') d = l.v < r.v ? -1 : l.v > r.v ? 1 : 0
          else if (l.k === 't') d = cmpCode(l.v, r.v)
          else d = (l.v ? 1 : 0) - (r.v ? 1 : 0)
          const res = { '=': d === 0, '<>': d !== 0, '<': d < 0, '<=': d <= 0, '>': d > 0, '>=': d >= 0 }[n.op]
          return { k: 'b', v: res }
        }
        const a = toNum(l)
        if (a.k !== 'n') return a
        const b = toNum(r)
        if (b.k !== 'n') return b
        switch (n.op) {
          case '+':
            return fin(a.v + b.v)
          case '-':
            return fin(a.v - b.v)
          case '*':
            return fin(a.v * b.v)
          case '/':
            return b.v === 0 ? err('#DIV/0!') : fin(a.v / b.v)
          default:
            return fin(Math.pow(a.v, b.v))
        }
      }
    }
    return err('#ERR!')
  }

  const res = new Map()
  for (const addr of cells.keys()) res.set(addr, cellValue(addr))
  return res
}
"}

