import { readFileSync } from 'node:fs'
import { parseFormula } from './parse.js'
import { evaluateAll } from './eval.js'
import { colIndex, colName, addrParts, formatValue } from './util.js'

const mode = process.argv.slice(2)
if (mode.length !== 1 || (mode[0] !== 'values' && mode[0] !== 'deps')) {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

const input = readFileSync(0, 'utf8')
const lines = input.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cells = new Map()
function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}
lines.forEach((raw, i) => {
  const s = raw.replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') return
  const m = /^[^ \t]*/.exec(s)
  const addr = m[0].toUpperCase()
  const rest = s.slice(m[0].length).replace(/^[ \t]+/, '')
  const p = addrParts(addr)
  if (!p) fail(`error: line ${i + 1}: invalid cell address ${addr}`)
  if (cells.has(addr)) fail(`error: line ${i + 1}: cell ${addr} is declared twice`)
  cells.set(addr, { addr, content: rest, col: colIndex(p.col), row: p.row })
})

const sorted = [...cells.values()].sort((a, b) => a.col - b.col || a.row - b.row)
for (const c of sorted) {
  if (c.content[0] === '=') c.ast = parseFormula(c.content.slice(1))
}

let out = ''
if (mode[0] === 'values') {
  const vals = evaluateAll(cells)
  for (const c of sorted) out += `${c.addr}=${formatValue(vals.get(c.addr))}\n`
} else {
  for (const c of sorted) {
    out += `${c.addr}:`
    if (c.ast && !c.ast.err) {
      const set = new Map()
      collect(c.ast, set)
      const l = [...set.values()].sort((a, b) => a.col - b.col || a.row - b.row)
      for (const x of l) out += ` ${x.addr}`
    }
    out += '\n'
  }
}
process.stdout.write(out)

function collect(n, set) {
  if (n.t === 'ref') {
    const p = addrParts(n.addr)
    if (p) set.set(n.addr, { addr: n.addr, col: colIndex(p.col), row: p.row })
  } else if (n.t === 'range') {
    const a = addrParts(n.a)
    const b = addrParts(n.b)
    if (!a || !b) return
    const c1 = Math.min(colIndex(a.col), colIndex(b.col))
    const c2 = Math.max(colIndex(a.col), colIndex(b.col))
    const r1 = Math.min(a.row, b.row)
    const r2 = Math.max(a.row, b.row)
    for (let c = c1; c <= c2; c++) for (let r = r1; r <= r2; r++) set.set(colName(c) + r, { addr: colName(c) + r, col: c, row: r })
  } else if (n.t === 'call') n.args.forEach((x) => collect(x, set))
  else if (n.t === 'bin') {
    collect(n.l, set)
    collect(n.r, set)
  } else if (n.t === 'un') collect(n.e, set)
}
"}

